const inputs = $items('Combine - Merge').map(i => ({
  url: i.json.result.fileUrl,
  filename: i.json.result.filename // optional, if you want it
}));
return [{
  json: {
    inputs,
    outputFormat: 'mp4',
    filters: [
      { filter: "[0:v]setpts=PTS-STARTPTS[v0];[0:a]aresample=async=1,asetpts=N/SR/TB[a0];[1:v]setpts=PTS-STARTPTS[v1];[1:a]aresample=async=1,asetpts=N/SR/TB[a1];[v0][a0][v1][a1]concat=n=2:v=1:a=1[v][a]" }
    ],
    options: [
      { option: "-map", argument: "[v]" },
      { option: "-map", argument: "[a]" },
      { option: "-c:v", argument: "libx264" },
      { option: "-c:a", argument: "aac" },
      { option: "-crf", argument: "23" },
      { option: "-pix_fmt", argument: "yuv420p" },
      { option: "-movflags", argument: "+faststart" }
    ]
  }
}];

